<?php
require_once __DIR__.'/../config/config.php';$user=require_employee_user();$pdo=db();$employee=employee_owner($pdo,$user);$status=trim((string)($_GET['status']??''));$allowedStatuses=['PENDING','APPROVED','REJECTED','CANCELLED'];$where='';$params=[$employee['id']];if(in_array($status,$allowedStatuses,true)){$where=' AND status=?';$params[]=$status;}$q=$pdo->prepare('SELECT * FROM profile_change_requests WHERE employee_id=?'.$where.' ORDER BY created_at DESC');$q->execute($params);$requests=$q->fetchAll();$pageTitle='My requests';require __DIR__.'/../includes/header.php';?><div class="flex justify-between items-end mb-7"><div><p class="text-sm text-slate-500">Track submitted profile changes</p><h1 class="font-display text-3xl font-bold mt-1">My requests</h1></div><a href="change-request.php" class="rounded-lg bg-teal-700 px-5 py-3 text-sm font-bold text-white">New request</a></div><div class="flex gap-2 mb-5 text-sm"><?php foreach([''=>'All','PENDING'=>'Pending','APPROVED'=>'Approved','REJECTED'=>'Rejected'] as $value=>$label):?><a href="?status=<?=$value?>" class="rounded-full border px-3 py-1.5 font-bold <?= $status===$value?'bg-teal-50 text-teal-700':''?>"><?=e($label)?></a><?php endforeach;?></div><section class="bg-white border rounded-xl p-6 overflow-x-auto"><table class="w-full text-left text-sm"><thead class="text-xs uppercase text-slate-400"><tr><th class="py-3">Request ID</th><th>Request type</th><th>Field</th><th>Submitted</th><th>Status</th><th>HR remarks</th><th></th></tr></thead><tbody class="divide-y"><?php foreach($requests as $request):?><tr><td class="py-3">#<?=e($request['id'])?></td><td><?=e($request['request_type'])?></td><td><?=e($request['requested_field'])?></td><td><?=e($request['created_at'])?></td><td><span class="font-bold"><?=e($request['status'])?></span></td><td><?=e($request['review_reason']??'—')?></td><td><a class="font-bold text-teal-700" href="request.php?id=<?=$request['id']?>">View</a></td></tr><?php endforeach;?></tbody></table><?php if(!$requests):?><p class="py-8 text-center text-slate-500">No requests found.</p><?php endif;?></section><?php require __DIR__.'/../includes/footer.php';